function applyDocumentZoom(scale){const viewport=$('#doc-viewport'),ratio=scale/documentZoom;const left=(viewport.scrollLeft+viewport.clientWidth/2)*ratio-viewport.clientWidth/2,top=(viewport.scrollTop+viewport.clientHeight/2)*ratio-viewport.clientHeight/2;documentZoom=scale;$('#doc-image').style.width=scale*100+'%';$('#doc-scale').textContent=Math.round(scale*100)+'%';$('#doc-zoom-minus').disabled=scale<=1;$('#doc-zoom-plus').disabled=scale>=4;viewport.scrollLeft=Math.max(0,left);viewport.scrollTop=Math.max(0,top)}
$('#zoom-document').onclick=()=>{const p=readerPages[(flip?.getCurrentPageIndex()||0)-1],pages=documentPages();let index=pages.indexOf(p);if(index<0)index=pages.findIndex(x=>x.source>=(p?.source||0));showDocument(Math.max(0,index))};
