 const inner=document.createElement('div');inner.className='page-inner';inner.style.setProperty('--page-gutter',width*.10+'px');inner.style.setProperty('--page-vertical',height*.10+'px');const text=document.createElement('div');text.className='page-text';const footer=document.createElement('footer');footer.textContent='1 / 1';if(illustration){meter.classList.add('media-page','illustration-page','half-image');const img=document.createElement('img');inner.append(img);if(illustration.caption){const caption=document.createElement('div');caption.className='image-caption';appendCaption(caption,illustration.caption);inner.append(caption)}}inner.append(text,footer);meter.append(inner);document.body.append(meter);
