$('#font-minus').onclick=()=>applyFont(fontSizes[Math.max(0,fontSizes.indexOf(+$('#font-size').value)-1)]);$('#font-plus').onclick=()=>applyFont(fontSizes[Math.min(fontSizes.length-1,fontSizes.indexOf(+$('#font-size').value)+1)]);
