let paperPointer=null;
$('#stage').addEventListener('pointerdown',e=>{paperPointer={id:e.pointerId,x:e.clientX,y:e.clientY}});
$('#stage').addEventListener('pointercancel',()=>paperPointer=null);
$('#stage').addEventListener('pointerup',e=>{if($('#reader').classList.contains('reading-locked'))return;const p=paperPointer;paperPointer=null;if(flip&&flip.getState()!=='read')return;if(!p||p.id!==e.pointerId||Math.hypot(e.clientX-p.x,e.clientY-p.y)>12||!$('#reader').classList.contains('paper-only'))return;const page=e.target.closest('.page');if(!page)return;const bounds=page.getBoundingClientRect(),x=(e.clientX-bounds.left)/bounds.width,y=(e.clientY-bounds.top)/bounds.height;if(x>.25&&x<.75&&y>.15&&y<.85)$('#reader').classList.toggle('controls-visible')});

function navigateBook(direction){if(!flip||flip.getState()!=='read')return;const index=flip.getCurrentPageIndex(),last=readerPages.length+1;const end=direction<0?index===0:index+(flip.getOrientation()==='landscape'?1:0)>=last;if(end){if($('#reader').classList.contains('reading-locked')){toast(direction<0?'ถึงปกหน้าแล้ว':'ถึงปกหลังแล้ว');return}$('#back').click();return}direction<0?flip.flipPrev():flip.flipNext()}
$('#prev').onclick=()=>navigateBook(-1);$('#next').onclick=()=>navigateBook(1);
$('#back').onclick=async()=>{$('#reader').classList.remove('reading-locked');$('#unlock-reading').hidden=true;if(document.fullscreenElement)await document.exitFullscreen();$('#reader').classList.remove('focus-mode','paper-only','controls-visible','native-fullscreen');$('#reader').hidden=true;document.body.classList.remove('reading');fullscreenState();await Promise.allSettled([...bookWrites.values()]);await refresh().catch(e=>toast(e.message));if(returnToDiscovery){returnToDiscovery=false;$('#discover').showModal();$('#discover-content').scrollTop=discoveryScrollTop}$('#back').textContent='← ชั้นหนังสือ'};
