$('#signout').onclick=async()=>{if(session?.user.is_anonymous&&!confirm('ออกจากบัญชีทดลองแล้วอาจกลับเข้าอ่านหนังสือชุดนี้ไม่ได้ ต้องการออกหรือไม่?'))return;const {error}=await client.auth.signOut();if(error)toast(error.message);else{session=null;localStorage.removeItem('books-offline-owner');accountState();$('#reader').hidden=true;$('#login').showModal()}};




let shelfPage=0;
function fitShelf(){const shelf=$('#shelf');if(!shelf||!$('#library')||$('#library').hidden)return;const tiles=[...shelf.querySelectorAll('.book-tile')];const width=shelf.clientWidth-24,height=shelf.clientHeight-24;const spine=$('#library').classList.contains('spine-view');const spineWidth=window.innerWidth<600?42:50;const cols=Math.max(2,Math.floor(spine?(width-40)/(spineWidth+3):width/(window.innerWidth<600?112:155)));shelf.style.setProperty('--spine-width',spineWidth+'px');const rows=Math.max(1,Math.min(3,Math.floor(height/240)));const capacity=cols*rows,total=Math.max(1,Math.ceil(tiles.length/capacity));shelfPage=Math.min(shelfPage,total-1);const groupMap=new Map(tiles.map(tile=>[tile,tile.closest('.shelf-section')?.querySelector('h3')?.textContent||'หนังสือทั้งหมด']));const shown=tiles.slice(shelfPage*capacity,(shelfPage+1)*capacity);if(tiles.length){shelf.replaceChildren();for(let r=0;r<rows;r++){const zone=document.createElement('section');zone.className='compact-row';zone.style.setProperty('--cols',cols);zone.style.setProperty('--rows',rows);const rowTiles=shown.slice(r*cols,(r+1)*cols);const label=document.createElement('div');label.className='row-label';label.textContent=[...new Set(rowTiles.map(t=>groupMap.get(t)))].join(' · ')||'';zone.append(label);for(const tile of rowTiles)zone.append(tile);shelf.append(zone);const rowHeight=zone.clientHeight;const coverHeight=Math.max(80,Math.min(280,rowHeight-22-16-14-28-8,spine?280:(width/cols-24)*1.45));zone.style.setProperty('--cover-height',coverHeight+'px');zone.style.setProperty('--cover-width',coverHeight/1.45+'px');zone.style.setProperty('--cover-font',Math.max(13,Math.min(22,coverHeight/11))+'px')}}$('#shelf-page').textContent='ชุดชั้น '+(shelfPage+1)+' / '+total;$('#shelf-prev').disabled=shelfPage===0;$('#shelf-next').disabled=shelfPage===total-1;$('#shelf-pager').hidden=total<=1}
$('#shelf-prev').onclick=()=>{shelfPage--;renderShelf()};$('#shelf-next').onclick=()=>{shelfPage++;renderShelf()};
$('#filter-toggle').onclick=()=>{const panel=$('.library-filters');panel.hidden=!panel.hidden;$('#filter-toggle').setAttribute('aria-expanded',String(!panel.hidden));renderShelf()};
$('#manage-toggle').onclick=()=>{const active=$('#manage-toggle').getAttribute('aria-pressed')!=='true';$('#library').classList.toggle('managing',active);$('#manage-toggle').setAttribute('aria-pressed',String(active));renderShelf()};
window.addEventListener('resize',()=>{shelfPage=0;renderShelf()});
let unlockTimer;
function unlockReading(){clearTimeout(unlockTimer);$('#reader').classList.remove('reading-locked');$('#reader').classList.add('controls-visible');$('#unlock-reading').hidden=true;toast('ปลดล็อกการอ่านแล้ว')}
$('#lock-reading').onclick=()=>{const reader=$('#reader');reader.classList.add('paper-only','reading-locked');reader.classList.remove('controls-visible');$('#unlock-reading').hidden=false;fullscreenState();toast('ล็อกแล้ว · พลิกหน้าได้ตามปกติ กดรูปกุญแจค้าง 1 วินาทีเพื่อปลดล็อก')};
const unlockButton=$('#unlock-reading');
function cancelUnlockHold(){clearTimeout(unlockTimer);unlockTimer=null;unlockButton.classList.remove('holding')}
function startUnlockHold(e){e.preventDefault();e.stopPropagation();cancelUnlockHold();unlockButton.classList.add('holding');unlockTimer=setTimeout(()=>{cancelUnlockHold();unlockReading()},1000)}
unlockButton.addEventListener('touchstart',e=>{if(e.touches.length===1)startUnlockHold(e);else cancelUnlockHold()},{passive:false});
for(const event of ['touchend','touchcancel'])unlockButton.addEventListener(event,e=>{e.preventDefault();e.stopPropagation();cancelUnlockHold()},{passive:false});
unlockButton.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'||!e.isPrimary)return;startUnlockHold(e);try{e.currentTarget.setPointerCapture(e.pointerId)}catch{}});
for(const event of ['pointerup','pointercancel','lostpointercapture'])unlockButton.addEventListener(event,e=>{if(e.pointerType!=='touch')cancelUnlockHold()});
for(const event of ['contextmenu','selectstart','dragstart'])unlockButton.addEventListener(event,e=>e.preventDefault());
$('#unlock-reading').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();unlockReading()}});

function addBookMenu(tile,b){const button=document.createElement('button');button.className='book-menu-button';button.textContent='⋯';button.setAttribute('aria-label','จัดการหนังสือ '+b.title);button.onclick=()=>{const dialog=$('#book-menu'),list=$('#book-menu-actions');$('#book-menu-title').textContent=b.title;list.replaceChildren();const offline=document.createElement('button');offline.textContent='เก็บไว้อ่านออฟไลน์';offline.onclick=async()=>{offline.disabled=true;try{await downloadOfflineBook(b.id);dialog.close()}catch(e){toast('ยังไม่พร้อมอ่านออฟไลน์ · '+e.message)}finally{offline.disabled=false}};list.append(offline);const group=document.createElement('button');group.textContent='จัดกลุ่ม';group.onclick=()=>{dialog.close();tile.querySelector('.organize-book').click()};list.append(group);const state=bookMeta(b).state||'active';for(const [label,target] of state==='trash'?[['นำกลับชั้นหนังสือ','active']]:state==='archived'?[['นำกลับชั้นหนังสือ','active'],['ย้ายไปถังขยะ','trash']]:[['เก็บเข้าคลัง','archived'],['ย้ายไปถังขยะ','trash']]){const action=document.createElement('button');action.textContent=label;action.onclick=async()=>{dialog.close();await changeBookState(b.id,target)};list.append(action)}dialog.showModal()};tile.append(button)}
$('#book-menu-close').onclick=()=>$('#book-menu').close();

let spineView=false;try{spineView=localStorage.getItem('books-shelf-view')==='spine'}catch{}function applyShelfView(){document.querySelector('#library').classList.toggle('spine-view',spineView);document.querySelector('#shelf-view').textContent=spineView?'▤ โชว์ปก':'▥ โชว์สัน';document.querySelector('#shelf-view').setAttribute('aria-pressed',String(spineView))}document.querySelector('#shelf-view').onclick=()=>{spineView=!spineView;try{localStorage.setItem('books-shelf-view',spineView?'spine':'cover')}catch{}applyShelfView();shelfPage=0;renderShelf()};applyShelfView();

const defaultBookPrompt='ตอบคำถามให้ถูกต้องครบถ้วน เรียบเรียงเป็นหนังสือภาษาไทยที่อ่านสนุก ความยาวประมาณ {length} {unit} มีบทนำ หัวข้อหลักและหัวข้อรอง ตัวอย่างใกล้ตัว และบทสรุป ใช้ย่อหน้าสั้น ไม่กล่าวซ้ำ ไม่แต่งข้อมูลหรือแหล่งอ้างอิง หากไม่แน่ใจให้ระบุข้อจำกัด ช่วยเสนอคำค้นภาพภาษาอังกฤษที่สอดคล้องกับแต่ละบท';
let aiOptions={provider:'gemini',model:'',prompt:defaultBookPrompt},aiConfigured=false;
async function aiRequest(body){if(!session)throw Error('กรุณาเข้าสู่ระบบก่อน');const r=await fetch(SUPABASE_URL+'/functions/v1/books-ai',{method:'POST',headers:{Authorization:'Bearer '+session.access_token,apikey:SUPABASE_KEY,'Content-Type':'application/json'},body:JSON.stringify(body)});let result;try{result=await r.json()}catch{throw Error('บริการ AI ตอบกลับไม่สำเร็จ')}if(!r.ok||result.error)throw Error(friendlyApiError(result.error||'เรียกบริการ AI ไม่สำเร็จ'));return result;}
function safeImageUrl(value){try{const u=new URL(value);return u.protocol==='https:'?u.href:''}catch{return ''}}
function applyCoverImage(node,b){const m=bookMeta(b);if(!m.coverImage)return;const img=document.createElement('img');img.className='cover-photo';img.alt='';img.referrerPolicy='no-referrer';img.src=m.coverImage;img.onerror=()=>img.remove();node.prepend(img);node.classList.add('photo-cover')}
function updateCoverPreview(){const title=$('#title').value.trim()||'ชื่อหนังสือ';$('#cover-preview-title').textContent=title;$('#cover-preview').style.background=$('#cover-mode').value==='custom'?$('#cover-color').value:'#465c86';const img=$('#cover-preview-image'),url=safeImageUrl($('#cover-url').value);img.hidden=!url;if(url&&img.getAttribute('src')!==url){$('#cover-image-status').textContent='กำลังตรวจรูปปก…';img.referrerPolicy='no-referrer';img.onload=()=>{$('#cover-image-status').textContent='โหลดรูปได้ · ชื่อปกมีพื้นรองแยกจากภาพ';img.hidden=false};img.onerror=()=>{$('#cover-image-status').textContent='โหลดรูปไม่ได้ จะใช้สีปกแทน กรุณาตรวจลิงก์';img.hidden=true};img.src=url}}
for(const id of ['title','cover-color','cover-url','cover-mode'])$('#'+id).addEventListener('input',updateCoverPreview);
function coverMetadata(){const raw=$('#cover-url').value.trim();if(raw&&!safeImageUrl(raw))throw Error('รูปปกต้องเป็น URL แบบ https');return{coverColor:$('#cover-mode').value==='custom'?$('#cover-color').value:null,coverImage:safeImageUrl(raw),coverCredit:$('#cover-credit').value.trim().slice(0,500)}}
function richSlice(runs,start=0,end=Infinity){let cursor=0;return runs.map(r=>{const from=Math.max(0,start-cursor),to=Math.min(r.text.length,end-cursor);cursor+=r.text.length;if(to<=from)return '';let text=esc(r.text.slice(from,to));if(r.bold)text='<strong>'+text+'</strong>';if(r.italic)text='<em>'+text+'</em>';if(r.heading)text='<span class="rich-heading">'+text+'</span>';return text}).join('')}
function parseRichEditor(root){const pages=[];let runs=[];const push=(text,style={})=>{if(text)runs.push({text,...style})};const flush=()=>{const content=runs.map(r=>r.text).join('');if(content.trim())pages.push({type:'text',textFormat:2,content,rich:runs});runs=[]};
 function visit(node,style={}){if(node.nodeType===3){push(node.textContent,style);return}if(node.nodeType!==1)return;const tag=node.tagName;if(['SCRIPT','STYLE','IFRAME','OBJECT','SVG','FORM','BUTTON','INPUT'].includes(tag))return;if(tag==='IMG'){const url=safeImageUrl(node.getAttribute('src'));if(url){flush();pages.push({type:'image',content:url,caption:node.getAttribute('alt')||'',external:true})}return}if(tag==='BR'){push('\n');return}const next={...style,bold:style.bold||['B','STRONG'].includes(tag)||/font-weight:\s*(bold|[6-9]00)/i.test(node.getAttribute('style')||''),italic:style.italic||['I','EM'].includes(tag),heading:style.heading||/^H[1-6]$/.test(tag)||node.classList.contains('rich-heading')};if(tag==='LI'){const siblings=[...node.parentNode.children].filter(x=>x.tagName==='LI');push(node.parentNode.tagName==='OL'?(siblings.indexOf(node)+1)+'. ':'• ')}for(const child of node.childNodes)visit(child,next);if(['P','DIV','LI','H1','H2','H3','H4','H5','H6','BLOCKQUOTE','TR','FIGCAPTION'].includes(tag))push('\n\n')}
 for(const child of root.childNodes)visit(child);flush();return pages}
function importHtml(html){const doc=new DOMParser().parseFromString(html,'text/html');const pages=parseRichEditor(doc.body);$('#rich-editor').innerHTML=pages.map(p=>p.type==='text'?richSlice(p.rich):'<img src="'+esc(p.content)+'" alt="'+esc(p.caption||'')+'" referrerpolicy="no-referrer">').join('');syncRichText();return pages}
function syncRichText(){const pages=parseRichEditor($('#rich-editor'));$('#text').value=pages.filter(p=>p.type==='text').map(p=>p.content).join('\n\n')}
$('#rich-editor').addEventListener('input',syncRichText);
$('#rich-editor').addEventListener('paste',e=>{const html=e.clipboardData.getData('text/html'),plain=e.clipboardData.getData('text/plain');e.preventDefault();const original=html?new DOMParser().parseFromString(html,'text/html'):null;const pages=original?parseRichEditor(original.body):textPages(plain).map(p=>({...p,rich:[{text:p.content}]}));const safe=pages.map(p=>p.type==='text'?richSlice(p.rich):'<img src="'+esc(p.content)+'" alt="'+esc(p.caption||'')+'" referrerpolicy="no-referrer">').join('');const selection=window.getSelection();if(selection.rangeCount&&$('#rich-editor').contains(selection.anchorNode)){const range=selection.getRangeAt(0);range.deleteContents();const fragment=range.createContextualFragment(safe),last=fragment.lastChild;range.insertNode(fragment);if(last){range.setStartAfter(last);range.collapse(true);selection.removeAllRanges();selection.addRange(range)}}else $('#rich-editor').insertAdjacentHTML('beforeend',safe);syncRichText();if(original&&original.querySelectorAll('img').length>pages.filter(p=>p.type==='image').length)$('#status').textContent='มีรูปบางส่วนไม่ได้มากับการคัดลอกหรือเป็นลิงก์ที่เข้าถึงไม่ได้ กรุณาตรวจร่างก่อนสร้างเล่ม';toast('วางเนื้อหาแล้ว · ตรวจรูปและข้อความก่อนสร้างเล่ม')});
$('#rich-clear').onclick=()=>{$('#rich-editor').replaceChildren();$('#text').value=''};
async function loadAiSettings(){const result=await aiRequest({action:'get'});aiConfigured=result.configured;aiOptions={...aiOptions,...result.options};$('#ai-default-prompt').value=aiOptions.prompt||defaultBookPrompt;$('#ai-settings-status').textContent=aiConfigured?'มีคีย์บันทึกแล้ว · เว้นช่องคีย์ว่างเพื่อใช้คีย์เดิม':'ยังไม่ได้บันทึกคีย์';if(aiOptions.model){$('#ai-model').innerHTML='<option value="'+esc(aiOptions.model)+'">'+esc(aiOptions.model)+'</option>'}}
$('#ai-settings-open').onclick=async()=>{$('#ai-settings').showModal();$('#ai-key').value='';$('#ai-default-prompt').value=aiOptions.prompt;try{await loadAiSettings();await loadImageSettings()}catch(e){$('#ai-settings-status').textContent=e.message}};
$('#ai-settings-close').onclick=()=>{$('#ai-key').value='';$('#image-key').value='';$('#ai-settings').close()};
$('#ai-prompt-reset').onclick=()=>$('#ai-default-prompt').value=defaultBookPrompt;
$('#ai-settings-form').onsubmit=async e=>{e.preventDefault();$('#ai-settings-save').disabled=true;try{const result=await aiRequest({action:'save',provider:'gemini',key:$('#ai-key').value,model:$('#ai-model').value,prompt:$('#ai-default-prompt').value});$('#ai-key').value='';aiConfigured=result.configured;aiOptions=result.options;$('#ai-settings-status').textContent='บันทึกแล้ว · โหลดโมเดลแล้วทดสอบก่อนสร้างหนังสือ'}catch(error){$('#ai-settings-status').textContent=error.message}finally{$('#ai-settings-save').disabled=false}};
$('#ai-models').onclick=async()=>{$('#ai-models').disabled=true;try{const r=await aiRequest({action:'models'});$('#ai-model').innerHTML=r.models.map(m=>'<option value="'+esc(m.id)+'">'+esc(m.name||m.id)+'</option>').join('');if(r.models.some(m=>m.id===aiOptions.model))$('#ai-model').value=aiOptions.model;$('#ai-settings-status').textContent='โหลด '+r.models.length+' โมเดล · เลือกแล้วบันทึกการตั้งค่า'}catch(e){$('#ai-settings-status').textContent=e.message}finally{$('#ai-models').disabled=false}};
$('#ai-test').onclick=async()=>{$('#ai-test').disabled=true;try{const r=await aiRequest({action:'test',model:$('#ai-model').value});const saved=await aiRequest({action:'save',provider:'gemini',model:r.model,prompt:$('#ai-default-prompt').value});aiOptions=saved.options;$('#ai-settings-status').textContent='เรียกโมเดล '+r.model+' สำเร็จจริง และบันทึกเป็นโมเดลสร้างหนังสือแล้ว'}catch(e){$('#ai-settings-status').textContent=e.message}finally{$('#ai-test').disabled=false}};
$('#ai-open').onclick=async()=>{try{await loadAiSettings();if(!aiConfigured){$('#ai-settings-open').click();return}$('#ai-book-prompt').value=aiOptions.prompt||defaultBookPrompt;$('#ai-create').showModal()}catch(e){toast(e.message)}};
$('#ai-create-close').onclick=()=>$('#ai-create').close();
$('#ai-unit').onchange=()=>{const characters=$('#ai-unit').value==='characters';Object.assign($('#ai-target'),{min:characters?'900':'1',max:characters?'30000':'30',value:characters?'9000':'10'})};
$('#ai-create-form').onsubmit=async e=>{e.preventDefault();$('#ai-generate').disabled=true;$('#ai-generation-status').textContent='กำลังเขียนและค้นภาพ… อาจใช้เวลาประมาณ 1–2 นาที';try{const result=await aiRequest({action:'generate',model:aiOptions.model,topic:$('#ai-topic').value,unit:$('#ai-unit').value,target:Number($('#ai-target').value),images:Number($('#ai-images').value),prompt:$('#ai-book-prompt').value});const draft=result.draft;$('#form').reset();selected=[];fileList();$('#title').value=draft.title.slice(0,200);let html='';for(const chapter of draft.chapters){html+='<h2>'+esc(chapter.heading)+'</h2>'+chapter.paragraphs.map(p=>'<p>'+esc(p)+'</p>').join('');if(chapter.image){const i=chapter.image;html+='<img src="'+esc(i.url)+'" alt="'+esc(chapter.heading)+'"><p>ภาพ: '+esc(i.artist)+' · '+esc(i.license)+'\n'+esc(i.source)+'</p>'}}importHtml(html);const first=draft.chapters.find(c=>c.image)?.image;if(first){$('#cover-url').value=first.url;$('#cover-credit').value=(first.artist+' · '+first.license+' · '+first.source).slice(0,500)}updateCoverPreview();$('#ai-create').close();$('#create').showModal();$('#status').textContent='ร่างจาก '+result.model+' · พบภาพ '+draft.chapters.filter(c=>c.image).length+' / '+$('#ai-images').value+' ภาพที่ขอ · กรุณาตรวจข้อมูลและภาพก่อนสร้างเล่ม '+(result.warnings||[]).map(friendlyApiError).join(' · ')}catch(e){$('#ai-generation-status').textContent=e.message}finally{$('#ai-generate').disabled=false}};

async function verifyIncomingImages(pages){const urls=[...new Set(pages.filter(p=>p.type==='image'&&p.content.startsWith('https://')).map(p=>p.content))];const failures=[];for(const url of urls){try{await new Promise((resolve,reject)=>{const img=new Image(),timeout=setTimeout(()=>{img.src='';reject(Error('timeout'))},15000);img.referrerPolicy='no-referrer';img.onload=()=>{clearTimeout(timeout);resolve()};img.onerror=()=>{clearTimeout(timeout);reject(Error('unavailable'))};img.src=url})}catch{failures.push(url)}}if(failures.length)throw Error('มีรูป '+failures.length+' รูปโหลดไม่ได้ กรุณาแก้ลิงก์หรือลบรูปที่เสียในร่างก่อนสร้างเล่ม')}


$('#image-layout').onchange=()=>{if(current&&!$('#reader').hidden)buildReader(bookMeta(current).anchor||{source:0,offset:0})};

function bookTextHtml(runs,start=0,end=Infinity){const content=runs.map(r=>r.text).join('');end=Math.min(end,content.length);const result=[];let cursor=start;while(cursor<end){if(content[cursor]==='\n'){cursor++;continue}const stop=content.indexOf('\n',cursor),finish=stop<0?end:Math.min(stop,end);let after=finish;while(after<content.length&&content[after]==='\n')after++;const line=content.slice(cursor,finish);let position=0;const heading=runs.some(r=>{const begin=position;position+=r.text.length;return r.heading&&position>cursor&&begin<finish});const continued=cursor>0&&content[cursor-1]!=='\n';const list=/^\s*(?:[•●▪*-]|\d+[.)])\s/.test(line);const cls=heading?'book-heading':list?'book-list':continued?'book-continuation':'book-paragraph';const gap=Math.min(2,Math.max(0,after-finish-1));result.push('<div class="'+cls+'" style="margin-bottom:'+gap*1.65+'em">'+richSlice(runs,cursor,finish)+'</div>');cursor=after>finish?after:finish;if(stop<0)break}return result.join('')}

async function loadImageSettings(){const r=await aiRequest({action:'image-get'});$('#image-provider').value=r.provider;$('#image-api-status').textContent=r.provider==='commons'?'ไม่ต้องใช้คีย์ · กดทดสอบเพื่อตรวจการเชื่อมต่อ':r.configured[r.provider]?'บันทึกคีย์แล้ว · ยังไม่ได้ทดสอบในการเปิดหน้านี้':'ยังไม่มีคีย์ของคลังภาพนี้'}
$('#image-provider').onchange=()=>{$('#image-key').value='';$('#image-api-preview').replaceChildren();$('#image-api-status').textContent='เลือกคลังภาพแล้ว · บันทึกเพื่อใช้กับหนังสือเล่มถัดไป'};
$('#image-save').onclick=async()=>{const button=$('#image-save');button.disabled=true;try{await aiRequest({action:'image-save',provider:$('#image-provider').value,key:$('#image-key').value});$('#image-key').value='';$('#image-api-status').textContent='บันทึกแล้ว · กดทดสอบเพื่อยืนยันว่าเชื่อมต่อได้'}catch(e){$('#image-api-status').textContent='ยังไม่พร้อมใช้ · '+e.message}finally{button.disabled=false}};
$('#image-test').onclick=async()=>{const button=$('#image-test');button.disabled=true;$('#image-api-preview').replaceChildren();try{const r=await aiRequest({action:'image-test',provider:$('#image-provider').value,query:'books'});$('#image-api-status').textContent=r.images.length?'เชื่อมต่อสำเร็จ · พร้อมใช้ · พบ '+r.images.length+' ภาพทดสอบ':'เชื่อมต่อสำเร็จ · คำค้นทดสอบนี้ไม่พบภาพ';for(const i of r.images.slice(0,3)){const figure=document.createElement('figure'),img=document.createElement('img'),caption=document.createElement('figcaption');img.src=i.url;img.alt=i.title||'ภาพทดสอบ';caption.textContent=i.artist+' · '+i.license;figure.append(img,caption);$('#image-api-preview').append(figure)}}catch(e){$('#image-api-status').textContent=e.message}finally{button.disabled=false}};

function apiTab(images){$('#api-text-panel').hidden=images;$('#api-image-panel').hidden=!images;$('#api-text-tab').setAttribute('aria-pressed',String(!images));$('#api-image-tab').setAttribute('aria-pressed',String(images))}$('#api-text-tab').onclick=()=>apiTab(false);$('#api-image-tab').onclick=()=>apiTab(true);

function appendCaption(el,text){for(const part of String(text).split(/(https:\/\/[^\s]+)/g)){if(part.startsWith('https://')){const link=document.createElement('a');link.href=part;link.target='_blank';link.rel='noopener noreferrer';link.textContent=part;el.append(link)}else el.append(document.createTextNode(part))}}

let discoveryBooks=[],discoveryIndex=0,discoveryMode='swipe',discoveryDrag=null,discoveryBusy=false,discoverySuppressClick=false;
function shuffleDiscovery(){discoveryBooks=books.filter(b=>!['archived','trash'].includes(bookMeta(b).state));for(let i=discoveryBooks.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[discoveryBooks[i],discoveryBooks[j]]=[discoveryBooks[j],discoveryBooks[i]]}discoveryIndex=0;renderDiscovery()}
function discoveryCover(b){const button=document.createElement('button');button.className='discovery-cover';button.setAttribute('aria-label','อ่าน '+b.title);const info=shelfInfo(b);button.style.setProperty('--cover',bookColor(b));button.innerHTML='<div class="cover"><small>'+esc(info.group)+'</small><h3>'+esc(b.title)+'</h3><div class="ornament">✦</div><small>'+esc(typeNames[info.type])+' · '+b.count+' หน้า</small></div>';applyCoverImage(button.querySelector('.cover'),b);button.onclick=()=>{if(discoverySuppressClick){discoverySuppressClick=false;return}openDiscoveryBook(b)};return button}
async function openDiscoveryBook(b){if(discoveryBusy)return;discoveryBusy=true;try{discoveryScrollTop=$('#discover-content').scrollTop;await openBook(b.id);returnToDiscovery=true;$('#back').textContent='← เลือกอ่านต่อ';$('#discover').close()}catch(e){toast(e.message)}finally{discoveryBusy=false}}
function renderDiscovery(){const host=$('#discover-content');host.replaceChildren();host.className=discoveryMode==='grid'?'discovery-masonry':'discovery-deck';$('#discover-navigation').hidden=discoveryMode==='grid'||!discoveryBooks.length;$('#discover-swipe').setAttribute('aria-pressed',String(discoveryMode==='swipe'));$('#discover-grid').setAttribute('aria-pressed',String(discoveryMode==='grid'));$('#discover-note').textContent=!discoveryBooks.length?'ยังไม่มีหนังสือบนชั้น':discoveryMode==='grid'?'ไถดูปก · แตะเล่มที่อยากอ่าน':'ปัดซ้ายหรือขวาเพื่อดูเล่มอื่น · แตะปกเพื่ออ่าน · '+(discoveryIndex+1)+' / '+discoveryBooks.length;if(discoveryMode==='grid'){const columns=document.createElement('div');columns.className='discovery-columns';for(const b of discoveryBooks)columns.append(discoveryCover(b));host.append(columns);return}if(!discoveryBooks.length)return;const card=discoveryCover(discoveryBooks[discoveryIndex]);host.append(card);card.addEventListener('pointerdown',e=>{if(!e.isPrimary||discoveryBusy)return;discoverySuppressClick=false;discoveryDrag={id:e.pointerId,x:e.clientX,y:e.clientY};card.setPointerCapture(e.pointerId)});card.addEventListener('pointermove',e=>{const drag=discoveryDrag;if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x;if(Math.abs(dx)>8){discoverySuppressClick=true;card.style.transition='none';card.style.transform='translateX('+dx+'px) rotate('+(dx/18)+'deg)';card.style.opacity=String(Math.max(.35,1-Math.abs(dx)/500))}});card.addEventListener('pointerup',e=>{const drag=discoveryDrag;discoveryDrag=null;if(!drag)return;const dx=e.clientX-drag.x;card.style.transition='';if(Math.abs(dx)>55)stepDiscovery(dx<0?1:-1);else{card.style.transform='';card.style.opacity=''}});card.addEventListener('pointercancel',()=>{discoveryDrag=null;discoverySuppressClick=true;card.style.transform='';card.style.opacity='';card.style.transition=''})}
function stepDiscovery(direction){if(discoveryBusy||!discoveryBooks.length)return;discoveryBusy=true;discoverySuppressClick=true;const card=$('#discover-content').querySelector('.discovery-cover');if(card){card.style.transition='transform .22s ease,opacity .22s ease';card.style.transform='translateX('+(direction>0?-110:110)+'%) rotate('+(direction>0?-14:14)+'deg)';card.style.opacity='0'}setTimeout(()=>{discoveryIndex=(discoveryIndex+direction+discoveryBooks.length)%discoveryBooks.length;renderDiscovery();discoveryBusy=false;discoverySuppressClick=false},matchMedia('(prefers-reduced-motion:reduce)').matches?0:220)}
$('#discover-open').onclick=()=>{discoveryMode='swipe';shuffleDiscovery();$('#discover').showModal()};$('#discover-close').onclick=()=>$('#discover').close();$('#discover-swipe').onclick=()=>{discoveryMode='swipe';renderDiscovery()};$('#discover-grid').onclick=()=>{discoveryMode='grid';renderDiscovery()};$('#discover-shuffle').onclick=shuffleDiscovery;$('#discover-prev').onclick=()=>stepDiscovery(-1);$('#discover-next').onclick=()=>stepDiscovery(1);$('#discover-read').onclick=()=>{if(discoveryBooks.length)openDiscoveryBook(discoveryBooks[discoveryIndex])};$('#discover').addEventListener('keydown',e=>{if(discoveryMode==='swipe'&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();e.stopPropagation();stepDiscovery(e.key==='ArrowRight'?1:-1)}});

function friendlyApiError(message){const value=String(message||'');const match=value.match(/HTTP\s*(\d{3})/i);if(!match)return value;const code=Number(match[1]);const provider=/Gemini/i.test(value)?'บริการ Gemini':/pexels/i.test(value)?'คลังภาพ Pexels':/unsplash/i.test(value)?'คลังภาพ Unsplash':'บริการ';const descriptions={400:'ข้อมูลที่ส่งไปยังไม่ถูกต้อง ลองตรวจค่าที่กรอกอีกครั้ง',401:'คีย์ไม่ถูกต้องหรือหมดอายุ กรุณาตรวจคีย์ที่บันทึกไว้',403:'บัญชีหรือคีย์นี้ยังไม่มีสิทธิ์ใช้งานที่เลือก',404:'ไม่พบโมเดลหรือบริการที่เลือก ลองโหลดรายการใหม่',408:'บริการใช้เวลานานเกินไป ลองใหม่อีกครั้ง',429:'ถึงขีดจำกัดการใช้งานแล้ว อาจเป็นโควตาหรือส่งคำขอถี่เกินไป ลองรอหรือตรวจโควตาของบัญชี',500:'บริการเกิดข้อผิดพลาดภายใน ลองใหม่อีกครั้งภายหลัง',502:'การเชื่อมต่อระหว่างบริการมีปัญหาชั่วคราว ลองใหม่อีกครั้ง',503:'บริการยังไม่พร้อมรับงาน อาจกำลังยุ่งหรือขัดข้องชั่วคราว ลองใหม่อีกครั้งภายหลัง',504:'บริการตอบช้าจนหมดเวลารอ ลองใหม่อีกครั้ง'};return provider+' · '+(descriptions[code]||'เรียกใช้งานไม่สำเร็จ กรุณาลองใหม่หรือตรวจการตั้งค่า')+' (HTTP '+code+')'}

for(const button of document.querySelectorAll('[data-library-location]'))button.onclick=()=>{offlineOnly=false;$('#shelf-state').value=button.dataset.libraryLocation;$('#display-menu').open=false;refresh().catch(e=>toast(e.message));toast(button.textContent)};

let returnToDiscovery=false,discoveryScrollTop=0;

function setDiscoveryFocus(enabled){const dialog=$('#discover');dialog.classList.toggle('discovery-focus',enabled);$('#discover-fullscreen').setAttribute('aria-pressed',String(enabled));$('#discover-exit-focus').hidden=!enabled}
$('#discover-fullscreen').onclick=async()=>{setDiscoveryFocus(true);const dialog=$('#discover');if(dialog.requestFullscreen&&document.fullscreenEnabled){try{await dialog.requestFullscreen()}catch{}}};
$('#discover-exit-focus').onclick=async()=>{setDiscoveryFocus(false);if(document.fullscreenElement===$('#discover'))try{await document.exitFullscreen()}catch{}};
$('#discover').addEventListener('close',()=>{setDiscoveryFocus(false);if(document.fullscreenElement===$('#discover'))document.exitFullscreen().catch(()=>{})});
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&$('#discover').classList.contains('discovery-native')){setDiscoveryFocus(false);$('#discover').classList.remove('discovery-native')}else if(document.fullscreenElement===$('#discover'))$('#discover').classList.add('discovery-native')});
$('#discover').addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#discover').classList.contains('discovery-focus')){e.preventDefault();e.stopPropagation();$('#discover-exit-focus').click()}});

const offlineDbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('books-offline-v1',1);r.onupgradeneeded=()=>{r.result.createObjectStore('books',{keyPath:'key'});r.result.createObjectStore('pending',{keyPath:'key'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
let offlineOnly=false;const offlineObjectUrls=new Map();
function offlineOwner(){return session?.user?.id||localStorage.getItem('books-offline-owner')||''}
async function offlineStore(store,operation,value){const db=await offlineDbPromise;return new Promise((resolve,reject)=>{const tx=db.transaction(store,operation==='getAll'||operation==='get'?'readonly':'readwrite'),os=tx.objectStore(store);const request=operation==='getAll'?os.getAll():os[operation](value);let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error)})}
async function offlineGet(id){const record=await offlineStore('books','get',offlineOwner()+':'+id);if(!record)return null;const book=structuredClone(record.book);for(const [key,blob] of Object.entries(record.assets)){const cacheKey=record.key+':'+key;if(!offlineObjectUrls.has(cacheKey))offlineObjectUrls.set(cacheKey,URL.createObjectURL(blob));const url=offlineObjectUrls.get(cacheKey);for(const p of book.pages)if(p.content==='offline:'+key)p.content=url;if(book.pages[0]?.libraryMeta?.coverImage==='offline:'+key)book.pages[0].libraryMeta.coverImage=url}return book}
async function offlineList(){const records=await offlineStore('books','getAll');return Promise.all(records.filter(r=>r.owner===offlineOwner()).map(r=>offlineGet(r.book.id)))}
async function downloadOfflineBook(id){if(!('serviceWorker' in navigator))throw Error('เบราว์เซอร์นี้ไม่รองรับการเก็บหน้าเว็บออฟไลน์');await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(Error('ยังเตรียมหน้าเว็บออฟไลน์ไม่ครบ ลองรีเฟรชแล้วดาวน์โหลดใหม่')),15000))]);if(!session||!navigator.onLine)throw Error('ต้องออนไลน์และเข้าสู่ระบบก่อนดาวน์โหลด');toast('กำลังเก็บหนังสือไว้ในเครื่อง…');const book=await apiRequest('/api/books/'+id),copy=structuredClone(book),assets={};const urls=[...new Set([...copy.pages.filter(p=>p.type!=='text').map(p=>p.content),copy.pages[0]?.libraryMeta?.coverImage].filter(Boolean))];for(let i=0;i<urls.length;i++){const response=await fetch(urls[i]);if(!response.ok)throw Error('ดาวน์โหลดไฟล์ไม่สำเร็จ (HTTP '+response.status+')');const blob=await response.blob();if(!blob.size)throw Error('ไฟล์ภาพหรือเอกสารว่าง');const key='asset'+i;assets[key]=blob;for(const p of copy.pages)if(p.content===urls[i])p.content='offline:'+key;if(copy.pages[0]?.libraryMeta?.coverImage===urls[i])copy.pages[0].libraryMeta.coverImage='offline:'+key}for(const [key,url] of offlineObjectUrls){if(key.startsWith(session.user.id+':'+id+':')){URL.revokeObjectURL(url);offlineObjectUrls.delete(key)}}copy.count=copy.pages.length;await offlineStore('books','put',{key:session.user.id+':'+id,owner:session.user.id,book:copy,assets,sourceFingerprint:offlineFingerprint(book),saved:new Date().toISOString()});localStorage.setItem('books-offline-owner',session.user.id);if(navigator.storage?.persist)await navigator.storage.persist();toast('เก็บครบแล้ว · พร้อมอ่านออฟไลน์บนอุปกรณ์นี้')}
async function offlinePatch(id,body){const key=offlineOwner()+':'+id,record=await offlineStore('books','get',key);if(!record)throw Error('เล่มนี้ยังไม่ได้ดาวน์โหลดไว้ในเครื่อง');if(body.meta){const meta={...body.meta};if(meta.coverImage?.startsWith('blob:'))delete meta.coverImage;body={...body,meta};record.book.pages[0].libraryMeta={...record.book.pages[0].libraryMeta,...meta}}if(Number.isInteger(body.position))record.book.position=body.position;await offlineStore('books','put',record);const existing=await offlineStore('pending','get',key);await offlineStore('pending','put',{key,owner:offlineOwner(),id,body:{...existing?.body,...body,meta:{...existing?.body?.meta,...body.meta}}});return {ok:true}}
async function syncOfflineProgress(){if(!navigator.onLine||!session)return;const pending=await offlineStore('pending','getAll');for(const item of pending.filter(p=>p.owner===session.user.id)){await apiRequest('/api/books/'+item.id,{method:'PATCH',body:JSON.stringify(item.body)});await offlineStore('pending','delete',item.key)}}
$('#offline-save').onclick=async()=>{const b=$('#offline-save');b.disabled=true;try{await downloadOfflineBook(current.id);b.textContent='✓ พร้อมอ่านออฟไลน์'}catch(e){toast('ยังไม่พร้อมอ่านออฟไลน์ · '+e.message)}finally{b.disabled=false}};
$('#offline-library').onclick=async()=>{offlineOnly=true;$('#offline-menu').open=false;books=await offlineList();renderShelf();toast('หนังสือที่เก็บในอุปกรณ์นี้ · '+books.length+' เล่ม')};
window.addEventListener('online',()=>{syncOfflineProgress().then(()=>toast('ออนไลน์แล้ว · ซิงก์ตำแหน่งอ่านเรียบร้อย')).catch(()=>toast('ยังซิงก์ไม่ได้ · เก็บตำแหน่งอ่านไว้ในเครื่องแล้ว'))});
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('ยังเตรียมหน้าเว็บออฟไลน์ไม่สำเร็จ'));

initAuth().catch(async e=>{books=await offlineList();renderShelf();toast(books.length?'เปิดห้องสมุดออฟไลน์ · '+books.length+' เล่ม':e.message)});

$('#offline-download-all').onclick=async()=>{const button=$('#offline-download-all'),status=$('#offline-all-status');if(!navigator.onLine||!session){status.textContent='ต้องออนไลน์และเข้าสู่ระบบเพื่อเตรียมไฟล์ก่อน';return}button.disabled=true;let success=0;const failures=[];try{await syncOfflineProgress();const all=await apiRequest('/api/books');const active=all.filter(b=>!['archived','trash'].includes(bookMeta(b).state));const records=await offlineStore('books','getAll');const mine=records.filter(r=>r.owner===session.user.id);const remoteById=new Map(all.map(b=>[b.id,b]));for(const record of mine){const remote=remoteById.get(record.book.id);if(!remote){await offlineStore('books','delete',record.key);continue}const remoteMeta=bookMeta(remote);record.book.title=remote.title;record.book.position=remote.position;record.book.created=remote.created;const localCover=record.book.pages[0]?.libraryMeta?.coverImage;record.book.pages[0].libraryMeta={...remoteMeta,...(localCover?{coverImage:localCover}:{})};await offlineStore('books','put',record)}if(!active.length){status.textContent='ซิงก์แล้ว · ไม่มีหนังสือบนชั้น ข้อมูลคลังและถังขยะปรับตรงกับออนไลน์แล้ว';return}for(let i=0;i<active.length;i++){status.textContent='กำลังเก็บ '+(i+1)+' / '+active.length+' · '+active[i].title;try{const existing=mine.find(r=>r.book.id===active[i].id);if(existing&&existing.sourceFingerprint===offlineFingerprint(active[i])){success++}else{await downloadOfflineBook(active[i].id);success++}}catch(e){failures.push(active[i].title+': '+e.message)}}status.textContent=failures.length?'พร้อมอ่าน '+success+' / '+active.length+' เล่ม · ยังเก็บไม่ครบ: '+failures.join(' · '):'ซิงก์แล้ว · พร้อมอ่านออฟไลน์ครบ '+success+' เล่ม · คลังและถังขยะตรงกับออนไลน์';toast(failures.length?'เตรียมสำเร็จ '+success+' เล่ม · ตรวจเล่มที่ยังเก็บไม่ครบในเมนูบัญชี':'พร้อมอ่านออฟไลน์ทุกเล่มบนชั้น')}catch(e){status.textContent=e.message}finally{if(offlineOnly){books=await offlineList();renderShelf()}button.disabled=false}};

function offlineFingerprint(book){return JSON.stringify({title:book.title,pages:book.pages.map(p=>{const {libraryMeta,...body}=p;let content=body.content;if(p.type!=='text'){try{content=new URL(content).pathname.replace(/^\/storage\/v1\/object\/(?:sign|public)\/paper-library\//,'')}catch{}}return {...body,content}}),cover:bookMeta(book).coverImage||'',color:bookMeta(book).coverColor||''})}
